const speechOldCrumbs=crumbs;crumbs=()=>{let x=speechOldCrumbs().replace('>vorbire</button>','>Părțile de vorbire</button>');for(const [id,name] of Object.entries(SPEECH_LESSONS))x=x.replace('>'+id+'</button>','>'+esc(name)+'</button>');for(const group of Object.values(SPEECH_ACT))for(const [id,name] of Object.entries(group))x=x.replace('>'+id+'</button>','>'+esc(name)+'</button>');if(route[2]==='substantiv'&&route[3]==='coloreaza')x=x.replace('>Colorează cuvintele</button>','>Colorează substantivele</button>');return x;};
const speechOldView=view;view=function(html){if(route[0]==='llr'&&!route[1])html=html.replace('<div class="cards">','<div class="cards">'+card('🧩 Părțile de vorbire','Descoperă cuvintele și joacă-te cu ele',"go('llr','vorbire')",'2026-11-25T00:00:00+02:00'));return speechOldView(html);};
function speechRows(lesson,act){return ({'cuvant/intrus':SPEECH_INTRUS,'cuvant/grupeaza':SPEECH_GROUP,'substantiv/recunoaste':SPEECH_NOUNS,'substantiv/numara':SPEECH_NUMBERS,'substantiv/numar':SPEECH_COUNT,'substantiv/plural':SPEECH_PLURAL,'substantiv/articulat':SPEECH_ARTICULATED,'substantiv/feminin':SPEECH_FEMININE})[lesson+'/'+act];}
function speechValue(id){return state['speech-'+id]||'';}function speechSet(id,value){state['speech-'+id]=value;let field=document.getElementById('speech-'+id);field.classList.remove('good','bad');let fb=document.getElementById('speech-feedback-'+id);if(fb)fb.textContent='';let result=document.getElementById('score');if(result)result.innerHTML='';}
function speechInput(id,answer){return `<input id="speech-${id}" class="entry" data-speech-answer="${esc(answer)}" data-speech-id="${id}" aria-label="Răspuns" value="${esc(speechValue(id))}" oninput="speechSet('${id}',this.value)" autocomplete="off">`;}
function speechSelect(id,answer,options){return `<select id="speech-${id}" class="entry" data-speech-answer="${esc(answer)}" data-speech-id="${id}" aria-label="Alege răspunsul" onchange="speechSet('${id}',this.value)"><option value="">Alege</option>${options.map(v=>`<option value="${esc(v)}" ${speechValue(id)===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`;}
const speechStyle=document.createElement('style');speechStyle.textContent=`.speech-words{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.speech-word{font:inherit;color:#24334a;background:#fff;border:1px solid #b8cce2;border-radius:10px;padding:9px 13px;min-height:44px}.speech-word[aria-pressed=true]{text-decoration:line-through;text-decoration-thickness:2px;background:#e5efff;border-color:#5578ca}.speech-word.speech-correct{background:#d9f2e1;border:2px solid #398755}.speech-word.speech-wrong{background:#fff0ef;border:2px solid #c86660}.speech-word:focus-visible{outline:3px solid #ffb540;outline-offset:2px}`;document.head.appendChild(speechStyle);
function speechOptions(id,options){state.speechOptions=state.speechOptions||{};return state.speechOptions[id]||(state.speechOptions[id]=vocabShuffle([...options]));}
function speechPick(id,value,button){const field=document.getElementById('speech-'+id),group=button.closest('.speech-words'),next=field.value===value?'':value;field.value=next;state['speech-'+id]=next;group.querySelectorAll('button').forEach(b=>{b.setAttribute('aria-pressed',String(b===button&&!!next));b.classList.remove('speech-correct','speech-wrong');});const fb=document.getElementById('speech-feedback-'+id);if(fb)fb.textContent='';const result=document.getElementById('score');if(result)result.innerHTML='';}
speechStyle.textContent+=`.speech-number{display:flex;position:relative;width:280px;max-width:100%;margin:10px 0 0;padding:4px;background:#edf1f6;border:1px solid #bdccd9;border-radius:24px}.speech-number-option{flex:1;font:inherit;color:#344b65;background:transparent;border:0;border-radius:20px;min-height:44px;padding:8px;cursor:pointer}.speech-number-option[aria-checked=true]{background:#d9e8ff;color:#243c70;font-weight:750}.speech-number-option.speech-correct[aria-checked=true]{background:#d9f2e1;box-shadow:inset 0 0 0 2px #398755}.speech-number-option.speech-wrong[aria-checked=true]{background:#fff0ef;box-shadow:inset 0 0 0 2px #c86660}.speech-number-option:focus-visible{outline:3px solid #ffb540;outline-offset:1px}`;
function speechNumber(id,answer,word){return `<span class="speech-number" role="radiogroup" aria-label="Numărul substantivului ${esc(word)}">${[['singular','Singular'],['plural','Plural']].map(([value,label])=>`<button type="button" role="radio" class="speech-number-option" aria-checked="${speechValue(id)===value}" onclick="speechNumberPick('${id}','${value}',this)" onkeydown="if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();const choices=this.parentElement.querySelectorAll('button');const other=choices[this===choices[0]?1:0];other.click();other.focus()}">${label}</button>`).join('')}<input type="hidden" id="speech-${id}" data-speech-answer="${esc(answer)}" data-speech-id="${id}" value="${esc(speechValue(id))}"></span>`;}
function speechNumberPick(id,value,button){const group=button.parentElement,field=document.getElementById('speech-'+id);field.value=value;group.querySelectorAll('button').forEach(b=>{b.setAttribute('aria-checked',String(b===button));b.classList.remove('speech-correct','speech-wrong');});speechSet(id,value);}
function speechVerify(){const fields=[...document.querySelectorAll('[data-speech-answer]')],correct=[];let attempted=0;for(const f of fields){let v=f.value.trim(),ok=!!v&&f.dataset.speechAnswer.split('|').map(norm).includes(norm(v));if(v)attempted++;f.classList.toggle('good',ok);f.classList.toggle('bad',!!v&&!ok);if(f.type==='hidden'){const selected=f.parentElement.querySelector('.speech-word[aria-pressed="true"],.speech-number-option[aria-checked="true"]');if(selected)selected.classList.add(ok?'speech-correct':'speech-wrong');}let fb=document.getElementById('speech-feedback-'+f.dataset.speechId);if(fb)fb.textContent=!v?'':ok?'Corect!':'Mai încearcă!';if(ok)correct.push(f.dataset.speechId);}let rewardIds=route[3]==='articulat'?[...new Set(correct.map(id=>id.slice(0,-1)))].filter(id=>correct.includes(id+'a')&&correct.includes(id+'b')):correct;let earned=rewardGrant('llr',rewardIds);let result=document.getElementById('score');result.innerHTML=`<div class="result">${attempted?'Răspunsuri completate: '+attempted+'. Corecte: '+correct.length+'.':'Completează un răspuns și verifică.'}</div>`+rewardMessage(earned,'llr');}
function speechIntruderHint(i){
 if(i===19)return 'Trei cuvinte exprimă numere, iar unul exprimă o acțiune.';
 if(i===21)return 'Trei cuvinte exprimă acțiuni, iar unul exprimă o însușire.';
 if(i===23)return 'Trei cuvinte exprimă însușiri, iar unul denumește o ființă, un lucru sau un fenomen al naturii.';
 const action=[1,2,5,6,9,10,20,22].includes(i);
 return 'Trei cuvinte denumesc ființe, lucruri sau fenomene ale naturii, iar unul exprimă '+(action?'o acțiune.':'o însușire.');
}
function speechSeries(n){state.speechSeries=n;render();window.scrollTo(0,0);}function speechRepeat(){state={};render();window.scrollTo(0,0);}
function speechRender(){let lesson=route[2],act=route[3];if(!lesson)return view(`<div class="hero"><h2>🧩 Părțile de vorbire</h2><p>Alege lecția!</p></div><div class="cards">${Object.entries(SPEECH_LESSONS).map(([id,title],i)=>card((i+1)+'. '+title,SPEECH_ACT[id]?'Învață și exersează':'În curând',`go('llr','vorbire','${id}')`,SPEECH_ACT[id]?(id==='adjectiv'?'2026-11-27T00:00:00+02:00':'2026-11-25T00:00:00+02:00'):undefined)).join('')}</div>`);
if(!SPEECH_ACT[lesson])return view(`<div class="hero"><h2>${esc(SPEECH_LESSONS[lesson]||'Lecție')}</h2><p>În curând! 🌱</p></div>`);
if(!act)return view(`<div class="hero"><h2>${esc(SPEECH_LESSONS[lesson])}</h2><p>Alege o activitate!</p></div><div class="cards">${card('📖 Învățăm','Descoperă pe scurt',`go('llr','vorbire','${lesson}','invata')`)}${Object.entries(SPEECH_ACT[lesson]).map(([id,title],i)=>card((i+1)+'. '+title,(lesson==='substantiv'&&['sortare','coloreaza','gen'].includes(id))?'24 de serii · câte 6 cuvinte':(lesson==='substantiv'&&id==='propozitie')?'24 de serii · câte 3 propoziții':(lesson==='cuvant'&&['coloreaza','grupeaza'].includes(id))?'12 serii · câte 6 cuvinte':'24 de exerciții · serii de câte 6',`go('llr','vorbire','${lesson}','${id}')`,(lesson==='adjectiv'||(lesson==='substantiv'&&['gen','recapitulare'].includes(id)))?'2026-11-27T00:00:00+02:00':undefined)).join('')}</div>`);
if(act==='invata'){let body=lesson==='cuvant'?'<p>Cuvintele pot denumi <b>ființe, lucruri sau fenomene</b> (copil, carte, ploaie), pot exprima <b>însușiri</b> (sprinten), <b>acțiuni</b> (citește), <b>numere</b> (trei).</p><p>După ceea ce exprimă, cuvintele se grupează în <b>părți de vorbire</b>. Vom descoperi substantivul, verbul, adjectivul, pronumele și numeralul.</p>':'<p><b>Substantivul</b> este partea de vorbire care denumește ființe, lucruri, fenomene ale naturii și alte aspecte ale lumii.</p><p><b>Numărul singular</b> arată, de obicei, un singur exemplar: un copil, o floare. <b>Numărul plural</b> arată, de obicei, mai multe: doi copii, două flori.</p><p>Unele substantive sunt masculine (un – doi), feminine (o – două) sau neutre (un – două). Unele cuvinte au forme diferite la feminin: bunic – bunică.</p><p><b>Model:</b> un copil → doi copii → copiii.</p>';return view(`<div class="hero"><h2>📖 Învățăm</h2><p>${esc(SPEECH_LESSONS[lesson])}</p></div><div class="panel">${body}</div>`);}
const rows=speechRows(lesson,act);if(!rows)return speechRender();const series=Math.max(0,Math.min(3,Number(state.speechSeries)||0)),start=series*6;const body=rows.slice(start,start+6).map((row,j)=>{let i=start+j,id=String(i),part='';if(lesson==='cuvant'&&act==='intrus')part=`<span class="speech-words" role="group" aria-label="Alege intrusul">${speechOptions(id,row[0]).map(word=>`<button type="button" class="speech-word" aria-pressed="${speechValue(id)===word}" onclick="speechPick('${id}',${esc(JSON.stringify(word))},this)">${esc(word)}</button>`).join('')}</span><input type="hidden" id="speech-${id}" data-speech-answer="${esc(row[1])}" data-speech-id="${id}" value="${esc(speechValue(id))}">`;else if(act==='grupeaza')part=`<b>${esc(row[0])}</b> → ${speechSelect(id,row[1],['ființă','lucru','fenomen al naturii','acțiune','însușire'])}`;else if(act==='recunoaste')part=`<b>${esc(row[0])}</b> → ${speechSelect(id,row[1],['ființă','lucru','fenomen al naturii'])}`;else if(act==='numara')part=`${speechSelect(id,row[1],['un','o','doi','două'])} <b>${esc(row[0])}</b>`;else if(act==='numar')part=`<b>${esc(row[0])}</b> ${speechNumber(id,row[1],row[0])}`;else if(act==='articulat'){let a=id+'a',b=id+'b';part=`<b>${esc(row[0])}</b> → ${speechInput(a,row[1])} → ${speechInput(b,row[2])}<div id="speech-feedback-${a}" class="speech-feedback" aria-live="polite"></div><div id="speech-feedback-${b}" class="speech-feedback" aria-live="polite"></div>`;}else part=`<b>${esc(row[0])}</b> → ${speechInput(id,row[1])}`;return `<div class="task"><p><b>${i+1}.</b> ${part}</p>${lesson==='cuvant'&&act==='intrus'?`<details class="speech-hint"><summary>💡 Indiciu</summary><p>${speechIntruderHint(i)}</p></details>`:''}<div id="speech-feedback-${id}" class="speech-feedback" aria-live="polite"></div></div>`;}).join('');let instruction=act==='intrus'?'Apasă pe intrus ca să îl tai, apoi verifică.':act==='articulat'?'Completează după model: copil → copii → copiii.':act==='numara'?'Alege un, o, doi sau două.':act==='plural'?'Scrie forma de plural.':act==='feminin'?'Scrie forma de feminin.':act==='numar'?'Alege numărul substantivului.':'Alege categoria potrivită.';
let textBox=act==='recunoaste'?SPEECH_NOUN_TEXTS[series]:'';return view(`<div class="hero"><p class="section-label">${esc(SPEECH_LESSONS[lesson])}</p><h2>${esc(SPEECH_ACT[lesson][act])}</h2><p>${instruction}</p><p>Seria ${series+1} din 4 · exercițiile ${start+1}–${start+6}</p></div><div class="panel">${body}${textBox?`<p class="rule">📖 ${esc(textBox)}</p>`:''}<div class="row"><button class="btn" onclick="speechVerify()">✓ Verifică</button>${series>0?`<button class="btn alt" onclick="speechSeries(${series-1})">Seria anterioară</button>`:''}${series<3?`<button class="btn" onclick="speechSeries(${series+1})">Seria următoare</button>`:`<button class="btn alt" onclick="speechRepeat()">Repetă</button>`}</div><div id="score" aria-live="polite"></div></div>`);}
