const nounGameStyle=document.createElement('style');nounGameStyle.textContent=`.noun-bank,.noun-boxes,.noun-colors{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.noun-word,.noun-box,.noun-color,.noun-option{font:inherit;color:#24334a;background:#fff;border:2px solid #b8cce2;border-radius:12px;min-height:48px;padding:9px 14px;cursor:pointer}.noun-word[aria-pressed=true],.noun-color[aria-pressed=true]{outline:3px solid #355eb7;outline-offset:2px}.noun-box{flex:1 1 240px;min-height:85px;text-align:left}.noun-box strong,.noun-box small,.noun-status{display:block}.noun-right{box-shadow:inset 0 0 0 3px #398755}.noun-wrong{box-shadow:inset 0 0 0 3px #c86660}.noun-option[aria-pressed=true]{text-decoration:line-through;text-decoration-thickness:2px;background:#e5efff;border-color:#5578ca}.noun-option.noun-right{background:#d9f2e1}.noun-option.noun-wrong{background:#fff0ef}.noun-sentence{font-size:1.17rem;line-height:2.5}.noun-token{display:inline;font:inherit;color:inherit;border:0;border-radius:5px;background:transparent;padding:3px 2px;cursor:pointer}.noun-token[aria-pressed=true]{background:#ffe993;box-shadow:0 0 0 1px #d7a93c}.noun-token.noun-wrong{box-shadow:0 0 0 2px #c86660}.noun-token.noun-right{box-shadow:0 0 0 2px #398755}.noun-word:focus-visible,.noun-box:focus-visible,.noun-color:focus-visible,.noun-token:focus-visible{outline:3px solid #ffb540;outline-offset:2px}`;document.head.appendChild(nounGameStyle);
