function grammarQuizRows(lesson,mode){
 if(lesson==='substantiv'&&mode==='gen')return NOUN_GENDER.map(([word,gender])=>({prompt:word,answer:gender,choices:['masculin','feminin','neutru'],hint:'Numără substantivul: un – doi, o – două sau un – două.'}));
 if(lesson==='substantiv'&&mode==='recapitulare')return NOUN_REVIEW.map(([prompt,answer,wrong])=>({prompt,answer,choices:[answer,...wrong]}));
 if(lesson==='adjectiv'&&mode==='recunoaste')return ADJ_EXAMPLES.map(([sentence,answer,noun,verb])=>({prompt:'',answer,choices:[noun,verb,'trei',answer]}));
 if(lesson==='adjectiv'&&mode==='propozitie')return ADJ_EXAMPLES.map(([sentence,answer,noun,verb])=>({prompt:sentence+' Care este adjectivul?',answer,choices:[noun,verb,answer]}));
 if(lesson==='adjectiv'&&mode==='acord')return ADJ_AGREEMENT.map(([prompt,answer,wrong])=>({prompt,answer,choices:[answer,...wrong]}));
 if(lesson==='adjectiv'&&mode==='pozitie')return ADJ_REORDER.map(([from,answer])=>({prompt:from,answer,input:true}));
 if(lesson==='adjectiv'&&mode==='formeaza')return ADJ_DERIVED.map(([word,answer,noun,verb])=>({prompt:word,answer,choices:[noun,verb,answer]}));
 if(lesson==='adjectiv'&&mode==='recapitulare')return ADJ_REVIEW.map(([prompt,answer,wrong])=>({prompt,answer,choices:[answer,...wrong]}));
 return [];
}
function grammarQuizStore(){return state.__grammarQuiz||(state.__grammarQuiz={answers:{},checks:{}});}
function grammarQuizPick(i,value){const m=grammarQuizStore();m.answers[i]=value;delete m.checks[i];render();}
function grammarQuizType(i,value){const m=grammarQuizStore();m.answers[i]=value;delete m.checks[i];const result=document.getElementById('score');if(result)result.innerHTML='';}
function grammarQuizVerify(){const m=grammarQuizStore(),rows=grammarQuizRows(route[2],route[3]),size=6,series=Math.max(0,Math.min(Math.ceil(rows.length/size)-1,Number(state.speechSeries)||0)),ids=[];let attempted=0;
 for(let i=series*size;i<Math.min(rows.length,(series+1)*size);i++){let value=String(m.answers[i]||'').trim();if(!value){delete m.checks[i];continue;}attempted++;const ok=norm(value)===norm(rows[i].answer);m.checks[i]=ok?'right':'wrong';if(ok)ids.push(String(i));}
 const earned=rewardGrant('llr',ids);render();const el=document.getElementById('score');if(el)el.innerHTML=`<div class="result">${attempted?'Răspunsuri completate: '+attempted+'. Corecte: '+ids.length+'.':'Completează un răspuns și verifică.'}</div>`+rewardMessage(earned,'llr');
}
function grammarQuizRender(lesson,mode){const rows=grammarQuizRows(lesson,mode),m=grammarQuizStore(),size=6,total=Math.ceil(rows.length/size),series=Math.max(0,Math.min(total-1,Number(state.speechSeries)||0)),start=series*size;
 const body=rows.slice(start,start+size).map((row,j)=>{const i=start+j,selected=m.answers[i]||'',check=m.checks[i];if(lesson==='substantiv'&&mode==='gen'){const options=['feminin','masculin','neutru'].map(value=>`<option value="${value}" ${selected===value?'selected':''}>${value}</option>`).join('');return `<div class="task"><p><b>${i+1}. ${esc(row.prompt)}</b> → <select class="entry ${check==='right'?'good':check==='wrong'?'bad':''}" aria-label="Genul substantivului ${esc(row.prompt)}" onchange="grammarQuizPick(${i},this.value)"><option value="">Alege</option>${options}</select></p>${row.hint?`<details><summary>💡 Indiciu</summary><p>${esc(row.hint)}</p></details>`:''}<div aria-live="polite">${check==='right'?'Corect!':check==='wrong'?'Mai încearcă!':''}</div></div>`;}let options=row.input?`<input class="entry ${check==='right'?'good':check==='wrong'?'bad':''}" aria-label="Răspunsul exercițiului ${i+1}" value="${esc(selected)}" oninput="grammarQuizType(${i},this.value)" placeholder="Scrie aici" autocomplete="off">`:`<div class="noun-bank">${speechOptions('grammar-'+lesson+'-'+mode+'-'+i,row.choices).map(value=>`<button type="button" class="noun-word grammar-option ${selected===value&&check?'noun-'+check:''}" aria-pressed="${selected===value}" onclick="grammarQuizPick(${i},${esc(JSON.stringify(value))})">${esc(value)}</button>`).join('')}</div>`;return `<div class="task"><p><b>${i+1}.</b> ${esc(row.prompt)}</p>${options}${row.hint?`<details><summary>💡 Indiciu</summary><p>${esc(row.hint)}</p></details>`:''}<div aria-live="polite">${check==='right'?'Corect!':check==='wrong'?'Mai încearcă!':''}</div></div>`;}).join('');
 return view(`<div class="hero"><p class="section-label">${esc(SPEECH_LESSONS[lesson])}</p><h2>${esc(SPEECH_ACT[lesson][mode])}</h2>${lesson==='substantiv'&&mode==='gen'?'<p>Alege genul substantivului.</p>':''}<p>Seria ${series+1} din ${total} · exercițiile ${start+1}–${Math.min(start+size,rows.length)}</p></div><div class="panel">${body}<div class="row"><button class="btn" onclick="grammarQuizVerify()">✓ Verifică</button>${series>0?`<button class="btn alt" onclick="speechSeries(${series-1})">Seria anterioară</button>`:''}${series<total-1?`<button class="btn" onclick="speechSeries(${series+1})">Seria următoare</button>`:`<button class="btn alt" onclick="speechRepeat()">Repetă</button>`}</div><div id="score" aria-live="polite"></div></div>`);
}

