const grammarQuizPrevious=speechRender;
speechRender=function(){const lesson=route[2],mode=route[3];if(lesson==='adjectiv'&&mode==='invata')return view(`<div class="hero"><h2>📖 Învățăm</h2><p>Adjectivul</p></div><div class="panel"><h3>REȚINE!</h3><p><b>Adjectivul</b> este partea de vorbire care arată însușiri ale ființelor, lucrurilor sau fenomenelor naturii.</p><p>Exemple: iepure <b>sprinten</b>, apă <b>cristalină</b>, fetiță <b>mărinimoasă</b>, ploaie <b>rece</b>.</p><p>Adjectivul poate sta după sau înaintea substantivului: <b>copilul vesel – veselul copil</b>.</p><p>Adjectivul se acordă în gen și număr cu substantivul: <b>băiat harnic – fată harnică – băieți harnici – fete harnice</b>.</p></div>`);if((lesson==='substantiv'&&['gen','recapitulare'].includes(mode))||(lesson==='adjectiv'&&['recunoaste','propozitie','acord','pozitie','formeaza','recapitulare'].includes(mode)))return grammarQuizRender(lesson,mode);return grammarQuizPrevious();};

/* Găsește adjectivele direct în propoziție. */
const ADJECTIVE_SENTENCES=[["Savantul curajos și curios cercetează codrul des.",["curajos","curios","des"]],["Bocceluța roșie alunecă spre prăpastia adâncă.",["roșie","adâncă"]],["Iepurele sprinten traversează luminișul însorit.",["sprinten","însorit"]],["Fetița mărinimoasă ajută un copil timid.",["mărinimoasă","timid"]],["Apa cristalină spală pietrele netede.",["cristalină","netede"]],["Motanul buclucaș caută jucăria albastră.",["buclucaș","albastră"]],["Copacul încovoiat umbrește cărarea îngustă.",["încovoiat","îngustă"]],["O ploaie rece udă frunzele uscate.",["rece","uscate"]],["Vrabia mică zboară spre cerdacul vechi.",["mică","vechi"]],["Bunicii harnici adună castanele maronii.",["harnici","maronii"]],["O fată veselă poartă o bocceluță ușoară.",["veselă","ușoară"]],["Pisica blândă urmărește un fluture galben.",["blândă","galben"]],["Câinele jucăuș împinge mingea rotundă.",["jucăuș","rotundă"]],["Florile înmiresmate colorează pajiștea verde.",["înmiresmate","verde"]],["Savantul atent observă un nor cenușiu.",["atent","cenușiu"]],["Vulpea isteață traversează pădurea deasă.",["isteață","deasă"]],["Bunica grijulie așază cheseaua mică pe cerdac.",["grijulie","mică"]],["Copiii zburdalnici construiesc un castel înalt.",["zburdalnici","înalt"]],["Vântul puternic scutură ramurile fragile.",["puternic","fragile"]],["Fetița curioasă descoperă o dună aurie.",["curioasă","aurie"]],["O lumină caldă cuprinde camera liniștită.",["caldă","liniștită"]],["Negustorul cinstit vinde mere proaspete.",["cinstit","proaspete"]],["O fetiță durdulie strânge frunzele arămii.",["durdulie","arămii"]],["Băiatul harnic desenează un peisaj frumos.",["harnic","frumos"]]];
function adjectiveStore(){return state.__adjectiveSentences||(state.__adjectiveSentences={answers:{},checks:{}});}
function adjectiveExpected(i){const [text,words]=ADJECTIVE_SENTENCES[i],wanted=words.map(norm);return nnTokens(text).flatMap((token,j)=>wanted.includes(norm(token))?[j]:[]);}
function adjectiveToken(i,j){const m=adjectiveStore(),selected=Array.isArray(m.answers[i])?m.answers[i]:[];m.answers[i]=selected.includes(j)?selected.filter(x=>x!==j):[...selected,j];delete m.checks[i];render();}
function adjectiveVerify(){const m=adjectiveStore(),series=Math.max(0,Math.min(3,Number(state.speechSeries)||0)),correct=[];let attempted=0;
 for(let i=series*6;i<series*6+6;i++){const got=Array.isArray(m.answers[i])?m.answers[i]:[],expected=adjectiveExpected(i);if(!got.length){delete m.checks[i];continue;}attempted++;const ok=got.length===expected.length&&expected.every(x=>got.includes(x));m.checks[i]=ok?'right':'wrong';if(ok)correct.push(String(i));}
 const earned=rewardGrant('llr',correct);render();const result=document.getElementById('score');if(result)result.innerHTML=`<div class="result">${attempted?'Răspunsuri completate: '+attempted+'. Corecte: '+correct.length+'.':'Selectează adjectivele și verifică.'}</div>`+rewardMessage(earned,'llr');
}
function adjectiveSentenceRender(){const m=adjectiveStore(),series=Math.max(0,Math.min(3,Number(state.speechSeries)||0)),start=series*6;
 const body=ADJECTIVE_SENTENCES.slice(start,start+6).map(([sentence],j)=>{const i=start+j,selected=Array.isArray(m.answers[i])?m.answers[i]:[],check=m.checks[i],expected=adjectiveExpected(i),tokens=nnTokens(sentence);return `<div class="task"><p class="noun-sentence"><b>${i+1}.</b> ${tokens.map((word,k)=>/^\p{L}/u.test(word)?`<button type="button" class="noun-token ${check&&selected.includes(k)?(expected.includes(k)?'noun-right':'noun-wrong'):''}" aria-pressed="${selected.includes(k)}" onclick="adjectiveToken(${i},${k})">${esc(word)}</button>`:esc(word)).join('')}</p><div aria-live="polite">${check==='right'?'Corect!':check==='wrong'?'Mai încearcă! Caută toate adjectivele.':''}</div></div>`;}).join('');
 return view(`<div class="hero"><p class="section-label">ADJECTIVUL</p><h2>Adjectivul în propoziție</h2><p>Seria ${series+1} din 4 · propozițiile ${start+1}–${start+6}</p></div><div class="panel"><p>Apasă pe toate adjectivele din fiecare propoziție. Cuvintele selectate se colorează cu galben.</p>${body}<div class="row"><button class="btn" onclick="adjectiveVerify()">✓ Verifică</button>${series>0?`<button class="btn alt" onclick="speechSeries(${series-1})">Seria anterioară</button>`:''}${series<3?`<button class="btn" onclick="speechSeries(${series+1})">Seria următoare</button>`:`<button class="btn alt" onclick="speechRepeat()">Repetă</button>`}</div><div id="score" aria-live="polite"></div></div>`);
}
const adjectiveSentencePrevious=speechRender;
speechRender=function(){if(route[2]==='adjectiv'&&route[3]==='propozitie')return adjectiveSentenceRender();return adjectiveSentencePrevious();};

const speechOldRender=render;render=function(){if(route[0]==='llr'&&route[1]==='vorbire')return speechRender();return speechOldRender();};
const speechOldLoad=loadProgress;loadProgress=function(){return route[0]==='llr'&&route[1]==='vorbire'&&route.length>3?{}:speechOldLoad();};
const speechResolved=routeFromPath();if(JSON.stringify(speechResolved)!==JSON.stringify(route)){route=speechResolved;state=loadProgress();}render();
